struct lapbeth_work {
	struct work_struct work;
	struct net_device *dev;
};

static void lapbeth_new_device_work(struct work_struct *work)
{
	struct lapbeth_work *lw = container_of(work, struct lapbeth_work, work);
	struct net_device *dev = lw->dev;

	rtnl_lock();
	if (dev->flags & IFF_UP)
		if (!lapbeth_get_x25_dev(dev))
			lapbeth_new_device(dev);
	rtnl_unlock();

	dev_put(dev);
	kfree(lw);
}

